        S.add("commutator (A) (3) 添字の付け替え l = j-1", a1, a2)
        S.add("commutator (A) (4) 指数法則 [theorem_exp_product n=1]", a2, a3)
        S.add("commutator (A) (5) l=0 の項と l=M の項の入れ替え", a3, a4)
